def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Count outcomes in current match
    cc = cd = dc = dd = 0
    for me, opp in history:
        if me == 'C':
            if opp == 'C':
                cc += 1
            else:
                cd += 1
        else:
            if opp == 'C':
                dc += 1
            else:
                dd += 1

    # Detect likely random opponent: near 50% cooperation and many defections
    opp_c = cc + dc
    opp_d = cd + dd
    if n >= 6:
        coop_rate = opp_c / n
        if 0.35 <= coop_rate <= 0.65:
            # If we've defected and they still mix, likely random
            if dc + dd >= 3:
                # Against random, defect is better long-term
                return 'D'

    # Last round: if we're behind or tied with defector, defect
    if n == 99:
        return 'D'

    # If opponent just defected, retaliate. If they defect twice in a row, keep defecting until they cooperate
    if n >= 2:
        last_me, last_opp = history[-1]
        prev_me, prev_opp = history[-2]
        if last_opp == 'D' and prev_opp == 'D':
            # Opponent is a persistent defector - defect
            return 'D'
        if last_opp == 'D':
            # Single defection - retaliate once
            return 'D'

    # If we defected last round and opponent cooperated, exploit again? 
    # But be careful not to trigger endless retaliation
    if n >= 1:
        last_me, last_opp = history[-1]
        if last_me == 'D' and last_opp == 'C':
            # We successfully exploited - try again with some probability
            if rng.random() < 0.6:
                return 'D'

    # Detecting all-cooperator: keep exploiting
    if n >= 4 and opp_d == 0:
        # Opponent has always cooperated - exploit
        return 'D'

    # Detect all-defector: defect
    if n >= 4 and opp_c == 0:
        return 'D'

    # Tit-for-tat with forgiveness: cooperate unless opponent defected in last 2 rounds
    if n >= 1:
        last_me, last_opp = history[-1]
        if last_opp == 'D':
            return 'D'

    # Mutual cooperation streak: keep cooperating
    return 'C'
